import { readFileSync, readdirSync } from "node:fs";
import { resolve, basename, join } from "node:path";
import { parseEvidenceIndex, validateEvidenceIndex } from "/Users/drewritter/prime-rad/gauntlet/.worktrees/conversation-assessment/src/context/scoped-read.ts";
const dir = resolve("docs/experiments/2026-09-08-conversation-release");
const cases = JSON.parse(readFileSync(join(dir,"cases.json"),"utf8")).cases;
const expected = JSON.parse(readFileSync(join(dir,"expected.json"),"utf8"));
let total = 0;
for (const row of cases) {
 const retained = row.evidence_root.startsWith("/srv/");
 const root = retained ? join("/Users/drewritter/prime-rad/superpowers-evals/.worktrees/conversation-assessment/results/conversation-release/known", basename(resolve(row.evidence_root,"..")),"evidence") : resolve(dir,row.evidence_root);
 const indexFile = retained ? join(root,"index.json") : resolve(dir,row.evidence_index);
 const index = parseEvidenceIndex(JSON.parse(readFileSync(indexFile,"utf8")));
 validateEvidenceIndex(root,index);
 for (const file of index.files) if (/(^|\/)(expected\.json|rubric\.md|rubrics|conversation-input|gauntlet-agent|result\.(json|md)|corpus-manifest\.json)(\/|$)/.test(file)) throw new Error("Private assessment input indexed: "+file);
 for (const c of expected[row.id].criteria) for (const decisive of c.decisive_evidence) if (!index.files.includes(decisive.path)) throw new Error(row.id+" decisive path absent: "+decisive.path);
 const rubric = readFileSync(resolve(dir,row.rubric),"utf8");
 if (expected[row.id].criteria.length !== rubric.split("\n").filter(line => line.startsWith("- ")).length) throw new Error("Criterion count mismatch");
 for (const c of expected[row.id].criteria) if (!rubric.includes(c.criterion)) throw new Error("Criterion bytes differ");
 if (retained && rubric !== readFileSync(resolve(root,"../conversation-input/rubric.md"),"utf8")) throw new Error("Original rubric differs");
 if (!retained) { const actual = readdirSync(root,{recursive:true,withFileTypes:true}).filter(e=>e.isFile()).map(e=>resolve(e.parentPath,e.name).slice(root.length+1)).filter(p=>p!=="index.json").sort(); if (JSON.stringify(actual)!==JSON.stringify(index.files)) throw new Error("Constructed index omits a file"); }
 total += index.files.length;
 console.log(row.id+": index valid ("+index.files.length+" files), criterion paths and rubric match");
}
console.log("Validated "+cases.length+" indexes / "+total+" indexed files.");
